int main(void){jbd_stream_t s;jbd_battery_data_t d={0};jbd_stream_init(&s);assert(jbd_stream_feed(&s,BASIC,10,&d)==JBD_FEED_NONE);assert(jbd_stream_feed(&s,BASIC+10,sizeof(BASIC)-10,&d)==JBD_FEED_UPDATED);assert(d.voltage_mv==79740&&d.current_ma==0&&d.remaining_mah==13620&&d.nominal_mah==20000&&d.cycles==40&&d.soc==67&&d.cell_count==24);assert(jbd_stream_feed(&s,CELLS,sizeof(CELLS),&d)==JBD_FEED_UPDATED);assert(d.cells_received==24&&d.cell_mv[0]==3323&&d.cell_mv[23]==3321);uint8_t bad[sizeof BASIC];memcpy(bad,BASIC,sizeof bad);bad[8]^=1;assert(jbd_stream_feed(&s,bad,sizeof bad,&d)==JBD_FEED_BAD_FRAME);puts("JBD captured-frame parsing: PASS");return 0;}
